return ['po-revision-date'=>'2025-04-17 20:34:08+0000','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','x-generator'=>'GlotPress/4.0.3','language'=>'uk_UA','project-id-version'=>'Plugins - Admin and Site Enhancements (ASE) - Stable (latest release)','messages'=>['(Default is \'secret\')'=>'(За замовчуванням - "секретно")','(Default is 160px)'=>'(За замовчуванням 160px)','(filtered from _MAX_ total entries)'=>'(відфільтровано з _MAX_ записів)','1 minute'=>'1 хвилина','10 minutes'=>'10 хвилин','120 seconds'=>'120 секунд','15 seconds'=>'15 секунд','2 minutes'=>'2 хвилини','3 minutes'=>'3 хвилини','30 seconds'=>'30 секунд','45 seconds'=>'45 секунд','5 minutes'=>'5 хвилин','60 seconds'=>'60 секунд','90 seconds'=>'90 секунд','<span class="faded">(Default is 1 minute)</span>'=>'<span class="faded">(За замовчуванням 1 хвилина)</span>','<span class="faded">(Default is 15 seconds)</span>'=>'<span class="faded">(Початковий - 15 секунд)</span>','<span class="field-sublabel sublabel-wide">Detect IP address from the following header first:</span>'=>'<span class="field-sublabel sublabel-wide">Спочатку визначте IP-адресу за таким заголовком:</span>','<span class="field-sublabel sublabel-wide">Host</span>'=>'<span class="field-sublabel sublabel-wide">Ведучий</span>','<span class="field-sublabel sublabel-wide">Password</span>'=>'<span class="field-sublabel sublabel-wide">Пароль</span>','<span class="field-sublabel sublabel-wide">Port</span>'=>'<span class="field-sublabel sublabel-wide">Порт</span>','<span class="field-sublabel sublabel-wide">Security</span>'=>'<span class="field-sublabel sublabel-wide">Безпека</span>','<span class="field-sublabel sublabel-wide">Send a test email to</span>'=>'<span class="field-sublabel sublabel-wide">Надішліть тестовий лист на адресу</span>','<span class="field-sublabel sublabel-wide">Sender email</span>'=>'<span class="field-sublabel sublabel-wide">Email відправника</span>','<span class="field-sublabel sublabel-wide">Sender name</span>'=>'<span class="field-sublabel sublabel-wide">Ім\'я відправника</span>','<span class="field-sublabel sublabel-wide">Username</span>'=>'<span class="field-sublabel sublabel-wide">Ім\'я користувача</span>','<strong>Code to insert after &lt;body&gt; with the priority of</strong>'=>'<strong>Код для вставки після &lt;body&gt; з пріоритетом</strong>','<strong>Code to insert before &lt;/head&gt; with the priority of</strong>'=>'<strong>Код для вставки перед &lt;/head&gt; з пріоритетом</strong>','<strong>Code to insert in footer section before &lt;/body&gt; with the priority of</strong>'=>'<strong>Код для вставки в розділ footer перед &lt;/body&gt; з пріоритетом</strong>','<strong>Error:</strong> Invalid email or incorrect password.'=>'<strong>Помилка:</strong> Невірний email або неправильний пароль.','<strong>Your ads.txt content:</strong>'=>'<strong>Ваш вміст ads.txt:</strong>','<strong>Your app-ads.txt content:</strong>'=>'<strong>Вміст вашого app-ads.txt:</strong>','ASE Pro YEAR-END SALE! 20% DISCOUNT. Lifetime Deal (LTD) available.'=>'ASE Pro РОЗПРОДАЖ НА КІНЕЦЬ РОКУ! ЗНИЖКА 20%. Доступна довічна угода (LTD).','AVIF Support Status'=>'Статус підтримки AVIF','AVIF Upload'=>'Завантаження AVIF','Add New'=>'Додати','Add Your Review'=>'Додати свій огляд','Add custom &lt;body&gt; class(es) on the singular view of some or all public post types. Compatible with classes already added using <a href="https://wordpress.org/plugins/wp-custom-body-class" target="_blank">Custom Body Class plugin</a>.'=>'Додавання кастомних класів &lt;body&gt; до деяких або всіх типів публічних дописів у єдиному поданні. Сумісний з класами, вже доданими за допомогою <a href="https://wordpress.org/plugins/wp-custom-body-class" target="_blank">плагіна Custom Body Class</a>.','Add custom CSS on all admin pages for all user roles.'=>'Додайте кастомний CSS на всіх сторінках адміністратора для всіх ролей користувачів.','Add custom CSS on all frontend pages for all user roles.'=>'Додайте кастомний CSS на всіх сторінках інтерфейсу для всіх ролей користувачів.','Admin Interface'=>'Інтерфейс адміністратора','Admin Menu'=>'Меню адміністратора','Admin Menu Organizer'=>'Органайзер меню адміністратора','Admin Menu Settings'=>'Налаштування меню адміністратора','Admin Notices'=>'Повідомлення адміністратора','Admin and Site Enhancements (ASE)'=>'Admin and Site Enhancements (ASE)','After duplication, redirect to:'=>'Після дублювання перенаправте на:','After saving the settings above, check if everything is configured properly below.'=>'Після збереження налаштувань вище, перевірте, чи все налаштовано належним чином нижче.','Allow Custom Navigation Menu Items to Open in New Tab'=>'Дозволити користувацькі пункти меню навігації відкривати на новій вкладці','Allow custom navigation menu items to have links that open in new browser tab via target="_blank" attribute. The rel="noopener noreferrer nofollow" attribute will also be added for enhanced security and SEO benefits.'=>'Дозвольте кастомним пунктам навігаційного меню мати посилання, які відкриваються в новій вкладці браузера через атрибут target="_blank". Атрибут rel="noopener noreferrer nofollow" також буде додано для підвищення безпеки та покращення SEO.','Allow some or all user roles to upload SVG files, which will then be sanitized to keep things secure.'=>'Дозвольте деяким або всім ролям користувачів завантажувати SVG-файли, які потім будуть очищені для забезпечення безпеки.','Also disable frontend block styles / CSS files for the selected post types.'=>'Також вимкніть стилі блоків інтерфейсу / CSS-файли для вибраних типів публікацій.','Attempts<br />Lockouts'=>'Спроби<br />Блокування','Auto-Publish Posts with Missed Schedule'=>'Автоматична публікація дописів з пропущеним розкладом','Background'=>'Фон','Bypass verification of SSL certificate. This would be insecure if mail is delivered across the internet but could help in certain local and/or containerized WordPress scenarios.'=>'Обійти перевірку SSL-сертифіката. Це буде небезпечно, якщо пошта доставляється через Інтернет, але може допомогти в певних локальних та/або контейнерних сценаріях WordPress.','Change Login URL'=>'Змінити URL-адресу для входу','Clean Up Admin Bar'=>'Очищення панелі адміністратора','Clean up admin pages by moving notices into a separate panel easily accessible via the admin bar.'=>'Очистіть сторінки адміністратора, перемістивши сповіщення в окрему панель, легко доступну через панель адміністратора.','Clean up and speed up the dashboard by completely disabling some or all widgets. Disabled widgets won\'t load any assets nor show up under Screen Options.'=>'Очистіть і пришвидшіть роботу інформаційної панелі, повністю вимкнувши деякі або всі віджети. Вимкнені віджети не завантажуватимуть жодних ресурсів і не відображатимуться в параметрах екрана.','Click to view hidden admin notices'=>'Натисніть, щоб переглянути приховані повідомлення адміністратора','Collapse'=>'Згорнути','Completely disable core, theme and plugin updates and auto-updates. Will also disable update checks, notices and emails.'=>'Повністю вимкнути оновлення ядра, тем і плагінів, а також автоматичне оновлення. Також вимкне перевірки оновлень, сповіщення та електронні листи.','Configure'=>'Налаштувати','Content Duplication'=>'Дублювання контенту','Content Management'=>'Управління контентом','Content Order'=>'Порядок вмісту','Currently on YEAR-END SALE. <a href="https://www.wpase.com/promo-ndg" target="_blank">20% discount</a>.'=>'Наразі триває РОЗПРОДАЖ НА КІНЕЦЬ РОКУ. <a href="https://www.wpase.com/promo-ndg" target="_blank">20% знижки</a>.','Curves'=>'Криві','Custom Admin CSS'=>'Користувацький адмінський CSS','Custom Admin Footer Text'=>'Користувацький текст нижнього колонтитула адміністратора','Custom Body Class'=>'Індивідуальний клас тіла','Custom Code'=>'Custom Code','Custom Frontend CSS'=>'Кастомний інтерфейсний CSS','Customize the order of the admin menu and optionally change menu item title or hide some items.'=>'Налаштуйте порядок меню адміністратора і за бажанням змініть назву пункту меню або приховайте деякі пункти.','Customize the text you see on the footer of wp-admin pages other than this ASE settings page.'=>'Налаштуйте текст, який ви бачите в нижньому колонтитулі сторінок wp-admin, окрім цієї сторінки налаштувань ASE.','DUPLICATE'=>'ДУБЛІКАТ','Default is %s'=>'За замовчанням %s','Default is 10. Larger number insert code closer to &lt;/body&gt;'=>'За замовчуванням 10. Більше число вставляє код ближче до &lt;/body&gt;','Default is 10. Larger number insert code closer to &lt;/head&gt;'=>'За замовчуванням 10. Більше число вставляє код ближче до &lt;/head&gt;','Default is 10. Smaller number insert code closer to &lt;body&gt;'=>'За замовчуванням 10. Менше число вставляє код ближче до &lt;тіла&gt;','Default text is: <em>Thank you for creating with <a href="https://wordpress.org/">WordPress</a></em>.'=>'Текст за замовчуванням: <em>Дякуємо, що створюєте за допомогою <a href="https://wordpress.org/">WordPress</a></em>.','Default text is: <em>Version %s</em>'=>'Текст за замовчуванням: <em>Версія %s</em>','Description'=>'Опис','Disable'=>'Вимкнути','Disable <strong>application passwords</strong> that was added since WordPress v5.6.'=>'Вимкніть <strong>паролі додатків</strong>, які було додано починаючи з WordPress v5.6','Disable <strong>block-based widgets settings screen</strong>. Restores the classic widgets settings screen when using a classic (non-block) theme. This has no effect on block themes.'=>'Вимкнути <strong>екран налаштувань блокових віджетів</strong>. Відновлює класичний екран налаштувань віджетів при використанні класичної (неблокової) теми. Це не впливає на блокові теми.','Disable <strong>emoji support for pages, posts and custom post types</strong> on the admin and frontend. The support is primarily useful for older browsers that do not have native support for it. Most modern browsers across different OSes and devices now have native support for it.'=>'Вимкніть <strong>підтримку емодзі для сторінок, дописів і кастомних типів до</strong> писів в адмінці та на фронтенді. Ця підтримка в першу чергу корисна для старих браузерів, які не мають вбудованої підтримки емодзі. Більшість сучасних браузерів на різних ОС і пристроях тепер мають вбудовану підтримку.','Disable <strong>jQuery Migrate</strong> script on the frontend, which should no longer be needed if your site uses modern theme and plugins.'=>'Вимкніть скрипт <strong>jQuery Migrate</strong> на фронтенді, який більше не потрібен, якщо ваш сайт використовує сучасні теми та плагіни.','Disable <strong>lazy loading of images</strong> that was natively added since WordPress v5.5.'=>'Вимкнути <strong>відкладене завантаження зображень</strong>, яке було додано в WordPress з версії 5.5.','Disable <strong>version number</strong> on static resource URLs referenced in &lt;head&gt;, which can disclose WordPress version number. Older versions(s) might contain unpatched security loophole(s). Applies to non-logged-in view of pages. This will also increase cacheability of static assets, but may have unintended consequences. Make sure you know what you are doing.'=>'Вимкніть <strong>номер версії</strong> на статичних URL-адресах ресурсів, на які посилаються в &lt;head&gt;, що може розкрити номер версії WordPress. Старіші версії можуть містити невиправлені уразливості. Стосується перегляду сторінок без входу в систему. Це також збільшить кешованість статичних ресурсів, але може мати непередбачувані наслідки. Переконайтеся, що ви знаєте, що робите.','Disable All Updates'=>'Вимкнути всі оновлення','Disable Comments'=>'Вимкнути коментарі','Disable Components'=>'Вимкнути компоненти','Disable Dashboard Widgets'=>'Вимкнути віджети інформаційної панелі','Disable Feeds'=>'Вимкнути канали','Disable Gutenberg'=>'Вимкнути Гутенберга','Disable REST API'=>'Вимкнути REST API','Disable REST API access for non-authenticated users and remove URL traces from &lt;head&gt;, HTTP headers and WP RSD endpoint.'=>'Вимкніть доступ до REST API для неавторизованих користувачів і видаліть трасування URL-адрес з &lt;head&gt;, HTTP-заголовків і кінцевої точки WP RSD.','Disable Smaller Components'=>'Вимкнути менші компоненти','Disable XML-RPC'=>'Вимкнути XML-RPC','Disable all RSS, Atom and RDF feeds. This includes feeds for posts, categories, tags, comments, authors and search. Also removes traces of feed URLs from &lt;head&gt;.'=>'Вимкнути всі RSS, Atom і RDF-канали. Сюди входять стрічки для постів, категорій, тегів, коментарів, авторів і пошуку. Також видаляє сліди URL-адрес стрічок з &lt;head&gt;.','Disable comments for some or all public post types. When disabled, existing comments will also be hidden on the frontend.'=>'Вимкнути коментарі для деяких або всіх типів публічних дописів. Якщо вимкнено, існуючі коментарі також будуть приховані на інтерфейсі.','Disable loading of <strong>Dashicons CSS and JS files</strong> on the front-end for public site visitors. This might break the layout or design of custom forms, including custom login forms, if they depend on Dashicons. Make sure to check those forms after disabling.'=>'Вимкнути завантаження <strong>CSS та JS файлів Dashicons</strong> на фронтенді для відвідувачів загальнодоступного сайту. Це може порушити макет або дизайн кастомних форм, включаючи кастомні форми входу, якщо вони залежать від Dashicons. Не забудьте перевірити ці форми після вимкнення.','Disable the <strong>Really Simple Discovery (RSD) &lt;link&gt; tag</strong> in &lt;head&gt;. It\'s not needed if your site is not using pingback or remote (XML-RPC) client to manage posts.'=>'Вимкніть <strong>тег Really Simple Discovery (RSD) &lt;link&gt;</strong> в &lt;head&gt;. Він не потрібен, якщо ваш сайт не використовує пінгбек або віддалений (XML-RPC) клієнт для керування публікаціями.','Disable the <strong>Windows Live Writer (WLW) manifest &lt;link&gt; tag</strong> in &lt;head&gt;. The WLW app was discontinued in 2017.'=>'Вимкніть <strong>тег &lt;link&gt; маніфесту Windows Live Writer (WLW</strong> ) у &lt;head&gt;. Додаток WLW було припинено у 2017 році.','Disable the <strong>generator &lt;meta&gt; tag</strong> in &lt;head&gt;, which discloses the WordPress version number. Older versions(s) might contain unpatched security loophole(s).'=>'Вимкніть <strong>тег генератора &lt;meta&gt;</strong> в &lt;head&gt;, який розкриває номер версії WordPress. Старіші версії можуть містити невиправлені уразливості.','Disable the <strong>plugin and theme editor</strong>.'=>'Відключити <strong>редактор плагінів і тем</strong>.','Disable the <strong>plugin and theme editor</strong>. <span class="warning-text">Note that wp-config.php in this site is not writeable and <code>DISALLOW_FILE_EDIT</code> constant is already defined there. You either need to make it writeable to make this setting functional, or, you need to manually change the value of <code>DISALLOW_FILE_EDIT</code> there.</span>'=>'Вимкнути <strong>редактор плагінів і тем</strong>. <span class="warning-text">Зауважте, що файл wp-config.php на цьому сайті недоступний для запису і активна константа <code>DISALLOW_FILE_EDIT</code> . Щоб цей параметр працював, Вам необхідно або зробити файл wp-config.php доступним для запису,  або вручну змінити значення константи <code>DISALLOW_FILE_EDIT</code>.</span>','Disable the Gutenberg block editor for some or all applicable post types.'=>'Вимкніть редактор блоків Gutenberg для деяких або всіх відповідних типів дописів.','Disable the default <strong>WordPress shortlink &lt;link&gt; tag</strong> in &lt;head&gt;. Ignored by search engines and has minimal practical use case. Usually, a dedicated shortlink plugin or service is preferred that allows for nice names in the short links and tracking of clicks when sharing the link on social media.'=>'Вимкніть стандартний <strong>тег короткого посилання WordPress &lt;link&gt;</strong> в &lt;head&gt;. Ігнорується пошуковими системами і має мінімальну практичну користь. Зазвичай, краще використовувати спеціальний плагін або сервіс, який дозволяє створювати гарні назви для коротких посилань і відстежувати кліки, коли ви ділитеся посиланням у соціальних мережах.','Dismiss'=>'Відхилити','Display Active Plugins First'=>'Спочатку показувати активні плагіни','Display System Summary'=>'Короткий огляд системи відображення','Display a panel showing and linking to all available sizes when viewing an image in the media library. Especially useful to quickly get the URL of a particular image size.'=>'Відображати панель з посиланнями на всі доступні розміри під час перегляду зображення у медіатеці. Особливо корисно для швидкого отримання URL-адреси зображення певного розміру.','Display active / activated plugins at the top of the Installed Plugins list. Useful when your site has many deactivated plugins for testing or development purposes.'=>'Відображати активні/активовані плагіни у верхній частині списку встановлених плагінів. Корисно, коли на вашому сайті є багато деактивованих плагінів з метою тестування або розробки.','Display the registration date and time in the users list table.'=>'Відображати дату та час реєстрації у переліку користувачів','Do more with <a href="https://www.wpase.com/upgrade-ndg-btm" target="_blank">ASE Pro</a>. Lifetime deal (LTD) <a href="https://www.wpase.com/upgrade-ndg-btm-prc" target="_blank">available</a>.'=>'Робіть більше з <a href="https://www.wpase.com/upgrade-ndg-btm" target="_blank">ASE Pro</a>. <a href="https://www.wpase.com/upgrade-ndg-btm-prc" target="_blank">Доступна</a> довічна угода (LTD).','Drag and drop menu items to the desired position. Optionally change 3rd party plugin/theme\'s menu item titles or hide some items until toggled by clicking "Show All" at the bottom of the admin menu.'=>'Перетягніть пункти меню в потрібне місце. За бажанням ви можете змінити заголовки пунктів меню сторонніх плагінів/тем або приховати деякі пункти, натиснувши кнопку "Показати все" внизу меню адміністратора.','Duplicate'=>'Дублювати','Duplicate %s'=>'Дублікат %s','Duplicate this as draft'=>'Продублюйте це як чернетку','Easily edit and validate your <a href="/ads.txt" target="_blank">ads.txt</a> and <a href="/app-ads.txt" target="_blank">app-ads.txt</a> content.'=>'Легко редагуйте та перевіряйте вміст ваших <a href="/ads.txt" target="_blank">ads.txt</a> та <a href="/app-ads.txt" target="_blank">app-ads.txt</a>.','Easily edit and validate your <a href="/robots.txt" target="_blank">robots.txt</a> content.'=>'Легко редагуйте та перевіряйте вміст <a href="/robots.txt" target="_blank">robots.txt</a>.','Easily enable enhancements and features that usually require multiple plugins.'=>'Легко вмикайте вдосконалення та функції, які зазвичай вимагають декількох плагінів.','Easily insert &lt;meta&gt;, &lt;link&gt;, &lt;script&gt; and &lt;style&gt; tags, Google Analytics, Tag Manager, AdSense, Ads Conversion and Optimize code, Facebook, TikTok and Twitter pixels, etc.'=>'Легко вставляйте теги &lt;meta&gt;, &lt;link&gt;, &lt;script&gt; і &lt;style&gt;, Google Analytics, Tag Manager, AdSense, Ads Conversion and Optimize code, пікселі Facebook, TikTok і Twitter тощо.','Easily replace any type of media file with a new one while retaining the existing media ID, publish date and file name. So, no existing links will break.'=>'Легко замінюйте будь-який тип медіафайлу на новий, зберігаючи існуючий ідентифікатор, дату публікації та ім\'я файлу. Таким чином, жодні існуючі посилання не будуть розірвані.','Edit'=>'Редагувати','Edit screen'=>'Екран редагування','Email'=>'Email','Email Address Obfuscator'=>'Обфускатор адреси електронної пошти','Email Delivery'=>'Доставка електронною поштою','Email address only'=>'Тільки адреса електронної пошти','Enable assignment of multiple roles during user account creation and editing. This maybe useful for working with roles not defined in WordPress core, e.g. from e-commerce or LMS plugins.'=>'Увімкнути призначення декількох ролей під час створення та редагування облікового запису користувача. Це може бути корисно для роботи з ролями, не визначеними в ядрі WordPress, наприклад, з плагінів електронної комерції або LMS.','Enable custom ordering of various "hierarchical" content types or those supporting "page attributes". A new \'Order\' sub-menu will appear for enabled content type(s). The "All {Posts}" list page for enabled post types in wp-admin will automatically use the custom order.'=>'Увімкніть користувацьке впорядкування різних "ієрархічних" типів контенту або тих, що підтримують "атрибути сторінок". Для увімкнених типів контенту з\'явиться нове підменю "Порядок". На сторінці списку "Всі {Posts}" для увімкнених типів дописів у wp-admin автоматично використовуватиметься кастомний порядок.','Enable debug mode and output the debug info into WordPress debug.log file.'=>'Увімкніть режим налагодження і виводьте інформацію про налагодження у файл WordPress debug.log.','Enable log in, log out and dynamic log in/out menu item for addition to any menu.'=>'Увімкніть пункт меню входу, виходу та динамічного входу/виходу для додавання до будь-якого меню.','Enable one-click duplication of pages, posts and custom posts. The corresponding taxonomy terms and post meta will also be duplicated.'=>'Увімкніть дублювання сторінок, дописів і кастомних дописів в один клік. Відповідні терміни таксономії та метадані допису також будуть продубльовані.','Enable pages, posts and/or custom post types to have permalinks that point to external URLs. The rel="noopener noreferrer nofollow" attribute will also be added for enhanced security and SEO benefits. Compatible with links added using <a href="https://wordpress.org/plugins/page-links-to/" target="_blank">Page Links To</a>.'=>'Увімкніть для сторінок, дописів та/або кастомних типів дописів постійні посилання, які вказують на зовнішні URL-адреси. Атрибут rel="noopener noreferrer nofollow" також буде додано для підвищення безпеки та покращення SEO. Сумісний з посиланнями, доданими за допомогою <a href="https://wordpress.org/plugins/page-links-to/" target="_blank">Page Links To</a>.','Enable uploading <a href="https://www.smashingmagazine.com/2021/09/modern-image-formats-avif-webp/" target="_blank">AVIF</a> files in the Media Library. You can convert your existing PNG, JPG and GIF files using a tool like <a href="https://squoosh.app/" target="_blank">Squoosh</a>.'=>'Увімкніть завантаження файлів <a href="https://www.smashingmagazine.com/2021/09/modern-image-formats-avif-webp/" target="_blank">AVIF</a> до медіатеки. Ви можете конвертувати наявні файли PNG, JPG та GIF за допомогою такого інструменту, як <a href="https://squoosh.app/" target="_blank">Squoosh</a>.','Enhance List Tables'=>'Покращення таблиць списків','Enhancements'=>'Покращення','Error:'=>'Помилка:','Excerpt'=>'Уривок','Expand'=>'Розкрити','External Permalinks'=>'Зовнішні посилання','Facebook'=>'Facebook','Failed Login Attempts Log'=>'Журнал невдалих спроб входу','Failed login attempts:'=>'Невдалі спроби входу:','Featured Image'=>'Головне зображення','Feedback'=>'Зворотній зв’язок','File Size'=>'Розмір файлу','Find Out More'=>'Дізнатися більше','First'=>'Перший','For example, if your site is behind a trusted proxy, it\'s a good idea to use the <code>HTTP_X_FORWARDED_FOR</code> header. Leave empty to use the default detection method.'=>'Наприклад, якщо ваш сайт працює за надійним проксі-сервером, доцільно використовувати заголовок <code>HTTP_X_FORWARDED_FOR</code>. Залиште пустим, щоб використовувати метод виявлення за замовчуванням.','Force all links to external sites in post content, where <a href="https://developer.wordpress.org/reference/hooks/the_content/" target="_blank">the_content</a> hook is used, to open in new browser tab via target="_blank" attribute. The rel="noopener noreferrer nofollow" attribute will also be added for enhanced security and SEO benefits.'=>'Змусьте всі посилання на зовнішні сайти в контенті постів, де використовується <a href="https://developer.wordpress.org/reference/hooks/the_content/" target="_blank">хук_content</a>, відкриватися в новій вкладці браузера через атрибут target="_blank". Атрибут rel="noopener noreferrer nofollow" також буде додано для підвищення безпеки та покращення SEO.','Force the usage of the sender name/email defined above. It will override those set by other plugins.'=>'Примусити використовувати ім\'я/пошту відправника, визначену вище. Це перевизначить ті, що встановлені іншими плагінами.','Full AVIF support requires that your server / hosting has <a href="https://php.watch/versions/8.1/gd-avif" target="_blank">GD extension</a> compiled with AVIF support in PHP 8.1 or greater, or, <a href="https://web.archive.org/web/20240104012918/https://avif.io/blog/tutorials/imagemagick/" target="_blank">ImageMagick 7.0.25 or greater</a> installed. Without either, you can still upload AVIF files but without auto-generation of the smaller thumbnail sizes. A majority of <a href="https://web.archive.org/web/20231207174740/https://avif.io/blog/articles/avif-browser-support/" target="_blank">modern desktop and mobile browsers</a> support the display of AVIF files.'=>'Повна підтримка AVIF вимагає, щоб на вашому сервері/хостингу було встановлено розширення <a href="https://php.watch/versions/8.1/gd-avif" target="_blank">GD</a>, скомпільоване з підтримкою AVIF в PHP 8.1 або новішої версії, або <a href="https://web.archive.org/web/20240104012918/https://avif.io/blog/tutorials/imagemagick/" target="_blank">ImageMagick 7.0.25 або новішої версії</a>. Без цього ви можете завантажувати AVIF-файли, але без автоматичної генерації мініатюр меншого розміру. Більшість <a href="https://web.archive.org/web/20231207174740/https://avif.io/blog/articles/avif-browser-support/" target="_blank">сучасних десктопних і мобільних браузерів</a> підтримують відображення файлів AVIF.','Get ASE Pro'=>'Отримайте ASE Pro','Get It Now'=>'Отримати зараз','Give the admin menu more room to better accommodate wider items.'=>'Додайте в меню адміністратора більше місця, щоб краще розмістити ширші пункти.','Heading'=>'Заголовок','Heartbeat Control'=>'Контроль серцебиття','Help others discover ASE and maybe <a href="https://www.wpase.com/trnslt-plgnndg" target="_blank">translate</a> to your language.'=>'Допоможіть іншим відкрити ASE і, можливо, <a href="https://www.wpase.com/trnslt-plgnndg" target="_blank">перекладіть</a> на свою мову.','Hide Admin Bar'=>'Приховати панель адміністратора','Hide Admin Notices'=>'Приховати повідомлення адміністратора','Hide admin bar on the frontend for all or some user roles.'=>'Приховати панель адміністратора у фронтенді для всіх або деяких ролей користувачів.','Hide until toggled'=>'Приховувати до перемикання','I\'ve reviewed'=>'Я переглянув','I\'ve shared'=>'Я поділився','IP Address<br />Last Username'=>'IP-адреса<br />Ім\'я користувача','If set, the following SMTP service/account wil be used to deliver your emails.'=>'Якщо встановлено, для доставки ваших імейлів буде використовуватися наступна служба/обліковий запис SMTP.','If set, the following sender name/email overrides WordPress core defaults but can still be overridden by other plugins that enables custom sender name/email, e.g. form plugins.'=>'Якщо встановлено, наступне ім\'я відправника/адреса електронної пошти замінює значення за замовчуванням ядра WordPress, але може бути замінено іншими плагінами, які дозволяють використовувати власні імена/адреси відправників, наприклад, плагінами форм.','If something goes wrong</strong> and you need to regain access to your account as an administrator, please visit the following URL: <br /><strong>%s</strong><br /><br />If you use <strong>Ninja Firewall</strong>, please uncheck "Block attempts to gain administrative privileges" in the Firewall Policies settings before you try to view as a non-admin user role to <strong>prevent being locked out</strong> of your admin account.'=>'Якщо щось пішло не так</strong> і вам потрібно відновити доступ до вашого облікового запису як адміністратора, будь ласка, відвідайте наступну URL-адресу: <br /><strong>%s</strong><br /><br />Якщо ви використовуєте <strong>Ninja Firewall</strong>, будь ласка, зніміть прапорець "Блокувати спроби отримати адміністративні привілеї" в налаштуваннях Політики брандмауера перед тим, як спробувати переглянути сайт з правами не-адміністратора, щоб <strong>уникнути блокування</strong> вашого облікового запису адміністратора.','Image Sizes Panel'=>'Панель розмірів зображень','Image Upload Control'=>'Контроль завантаження зображень','Improve the usefulness of listing pages for various post types and taxonomies, media, comments and users by adding / removing columns and elements.'=>'Покращуйте корисність сторінок списку для різних типів дописів і таксономій, медіа, коментарів і користувачів, додаючи/видаляючи стовпці та елементи.','Insert &lt;head&gt;, &lt;body&gt; and &lt;footer&gt; Code'=>'Вставте код &lt;head&gt;, &lt;body&gt; та &lt;footer&gt','Invalid username/email or incorrect password.'=>'Неправильне ім\'я користувача/електронна пошта або неправильний пароль.','Keep as is'=>'Зберегти як є','Last'=>'Остання','Last Attempt On'=>'Остання спроба','Last Login'=>'Останній вхід','Last Login Column'=>'Стовпчик "Останній вхід','Last Modified'=>'Остання зміна','Left Side'=>'Лівий бік','Lifetime Deal (LTD) is available for the Pro version of ASE.'=>'Довічна угода (LTD) доступна для Pro-версії ASE.','Limit Login Attempts'=>'Обмеження спроб входу','Limit to'=>'Обмеження до','Lines'=>'Позиції','List view'=>'Подивитися список','Log In/Out Menu'=>'Меню входу/виходу','Log In/Out | Register'=>'Вхід/Вихід | Реєстрація','Log when users on the site last logged in and display the date and time in the users list table.'=>'Записуйте час останнього входу користувачів на сайт і відображайте дату і час у таблиці списку користувачів.','Login ID Type'=>'Тип ідентифікатора для входу в систему','Looks like some of these free enhancements have been useful for your site?'=>'Схоже, деякі з цих безкоштовних розширень виявилися корисними для вашого сайту?','Maintenance Mode'=>'Режим технічного обслуговування','Maintenance mode is currently enabled for this site.'=>'Наразі для цього сайту ввімкнено режим технічного обслуговування.','Manage ads.txt and app-ads.txt'=>'Керування файлами ads.txt та app-ads.txt','Manage robots.txt'=>'Керування файлом robots.txt','Max height:'=>'Макс. висота:','Max width:'=>'Макс. ширина','Media Library Infinite Scrolling'=>'Медіатека Нескінченна прокрутка','Media Replacement'=>'Заміна носія','Modify'=>'Модифікувати','Modify the interval of the WordPress heartbeat API or disable it on admin pages, post creation/edit screens and/or the frontend. This will help reduce CPU load on the server.'=>'Змініть інтервал серцебиття API WordPress або вимкніть його на сторінках адміністратора, екранах створення/редагування постів та/або у фронтенді. Це допоможе зменшити навантаження на процесор на сервері.','Multiple User Roles'=>'Кілька ролей користувачів','Never'=>'Ніколи','New login URL:'=>'Нова URL-адреса для входу:','Next'=>'Наступне','No data available in table'=>'Даних у таблиці не знайдено','No matching records found'=>'Відповідних записів не знайдено','None'=>'Немає','Not available'=>'Не доступний','Notices'=>'Сповіщення','Obfuscate Author Slugs'=>'Заплутані авторські помилки','Obfuscate email address to prevent spam bots from harvesting them, but make it readable like a regular email address for human visitors.'=>'Завуалюйте адресу електронної пошти, щоб спам-боти не змогли її зібрати, але зробіть її читабельною, як звичайну адресу електронної пошти для відвідувачів.','Obfuscate publicly exposed author page URLs that shows the user slugs / usernames, e.g. <em>sitename.com/author/username1/</em> into <em>sitename.com/author/a6r5b8ytu9gp34bv/</em>, and output 404 errors for the original URLs. Also obfuscates in /wp-json/wp/v2/users/ REST API endpoint.'=>'Замінює загальнодоступні URL-адреси сторінок авторів, які показують імена користувачів, наприклад, <em>sitename.com/author/username1/</em> на <em>sitename.com/author/a6r5b8ytu9gp34bv/</em>, і виводить 404 помилки для оригінальних URL-адрес. Також заплутує в кінцевій точці /wp-json/wp/v2/users/ REST API.','On admin pages'=>'На сторінках адміністратора','On post creation and edit screens'=>'На екранах створення та редагування дописів','On the frontend'=>'На фронтенді','Only the latest 1,000 entries are kept in the database.'=>'У базі даних зберігаються лише останні 1,000 записів.','Oops, something went wrong</span>.<br />Please double check your settings and the destination email address.'=>'Ой, щось пішло не так</span>.<br />Будь ласка, перевірте ваші налаштування та адресу електронної пошти призначення.','Open All External Links in New Tab'=>'Відкрийте всі зовнішні посилання в новій вкладці','Optimizations'=>'Оптимізації','Or, help improve ASE by <a href="https://wordpress.org/support/plugin/admin-site-enhancements/" target="_blank">providing feedback</a>.'=>'Або допоможіть покращити ASE, <a href="https://wordpress.org/support/plugin/admin-site-enhancements/" target="_blank">надаючи зворотній зв’язок</a>.','Order'=>'Сортування','Password'=>'Пароль','Password Protection'=>'Захист паролем','Password protection is currently enabled for this site.'=>'Наразі для цього сайту ввімкнено захист паролем.','Password-protect the entire site to hide the content from public view and search engine bots / crawlers. Logged-in administrators can still access the site as usual.'=>'Захистіть весь сайт паролем, щоб приховати його вміст від публічного перегляду та пошукових ботів/пошукових роботів. Увійшовши в систему, адміністратори можуть отримати доступ до сайту, як зазвичай.','Perform 301 (permanent) redirect to the homepage for all 404 (not found) pages.'=>'Виконайте 301 (постійний) редирект на домашню сторінку для всіх 404 (не знайдено) сторінок.','Perform Replacement'=>'Виконати заміну','Please clear your cache</strong> after enabling or disabling maintenance mode. This ensures site visitors see either the maintenance page or the actual content of each page.'=>'Будь ласка, очистіть кеш</strong> після ввімкнення або вимкнення режиму технічного обслуговування. Це гарантує, що відвідувачі сайту бачитимуть або сторінку технічного обслуговування, або фактичний вміст кожної сторінки.','Please consider supporting ASE.'=>'Будь ласка, розгляньте можливість підтримати ASE.','Prevent bloating the database by limiting the number of revisions to keep for some or all post types supporting revisions.'=>'Запобігайте надмірному збільшенню бази даних, обмежуючи кількість редакцій, які слід зберігати для деяких або всіх типів записів, що підтримують редакції.','Prevent brute force attacks by limiting the number of failed login attempts allowed per IP address.'=>'Запобігайте атакам грубої сили, обмежуючи кількість невдалих спроб входу на одну IP-адресу.','Prevent smaller components from running or loading. Make the site more secure, load slightly faster and be more optimized for crawling by search engines.'=>'Запобігайте запуску або завантаженню менших компонентів. Зробіть сайт безпечнішим, трохи швидше завантажуватися і більш оптимізованим для сканування пошуковими системами.','Previous'=>'Попередній','Product Image'=>'Зображення товару','Protect your site from brute force, DOS and DDOS attacks via <a href="https://kinsta.com/blog/xmlrpc-php/#what-is-xmlrpcphp" target="_blank">XML-RPC</a>. Also disables trackbacks and pingbacks.'=>'Захистіть свій сайт від грубої сили, DOS і DDOS-атак через <a href="https://kinsta.com/blog/xmlrpc-php/#what-is-xmlrpcphp" target="_blank">XML-RPC</a>. Також відключає трекбек і пінгбек.','Re-enable infinite scrolling in the grid view of the media library. Useful for scrolling through a large library.'=>'Увімкнути нескінченну прокрутку в сітковому поданні медіатеки. Корисно для прокручування великої бібліотеки.','Redirect 404 to Homepage'=>'Перенаправлення 404 на домашню сторінку','Redirect After Login'=>'Перенаправлення після входу','Redirect After Logout'=>'Перенаправлення після виходу з системи','Redirect to:'=>'Перенаправлення на:','Registered'=>'Зареєстрований','Registration Date Column'=>'Колонка з датою реєстрації','Remove \'Howdy\''=>'Видалити "Привіт','Remove WordPress logo/menu'=>'Видалити логотип/меню WordPress','Remove comments column'=>'Видалити колонку коментарів','Remove comments counter/link'=>'Видалити лічильник коментарів/посилання','Remove customize menu'=>'Видалити меню налаштувань','Remove date column'=>'Видалити колонку з датою','Remove home icon and site name'=>'Видалити іконку "Додому" та назву сайту','Remove new content menu'=>'Видалити нове меню вмісту','Remove tags column (for posts)'=>'Видалити колонку тегів (для дописів)','Remove the Help tab and drawer'=>'Видаліть вкладку "Довідка" та панель','Remove updates counter/link'=>'Видалити лічильник/посилання на оновлення','Remove various elements from the admin bar.'=>'Видаліть різні елементи з панелі адміністратора.','Replace Media'=>'Замінити','Resize newly uploaded, large images to a smaller dimension and delete originally uploaded files. BMPs and non-transparent PNGs will be converted to JPGs and resized.'=>'Зменшити розмір нещодавно завантажених великих зображень до меншого розміру і видалити завантажені файли. BMP і непрозорі PNG-файли будуть перетворені в JPG і змінені в розмірах.','Restrict login ID to username or email address only.'=>'Обмежте ідентифікатор входу лише іменем користувача або адресою електронної пошти.','Review'=>'Відгук','Revisions Control'=>'Контроль редакцій','Right Side'=>'Права сторона','SSL'=>'SSL','SVG Upload'=>'Завантаження SVG','Save Changes'=>'Зберегти зміни','Search Engines Visibility Status'=>'Статус видимості в пошукових системах','Search engines are discouraged from indexing this site. Click to change the settings.'=>'Пошуковим системам не рекомендується індексувати цей сайт. Натисніть, щоб змінити налаштування.','Search:'=>'Пошук:','Security'=>'Безпека','Select New Media File'=>'Виберіть новий медіафайл','Select an Image'=>'Виберіть зображення','Send Now'=>'Надіслати Зараз','Sending test email...'=>'Відправлення тестового листа...','Set custom redirect URL for all or some user roles after login.'=>'Встановіть власну URL-адресу перенаправлення для всіх або деяких ролей користувачів після входу в систему.','Set custom redirect URL for all or some user roles after logout.'=>'Встановіть власну URL-адресу перенаправлення для всіх або деяких ролей користувачів після виходу з системи.','Set custom sender name and email. Optionally use external SMTP service to ensure notification and transactional emails from your site are being delivered to inboxes.'=>'Встановіть власне ім\'я відправника та адресу електронної пошти. За бажанням використовуйте зовнішній SMTP-сервіс, щоб забезпечити доставку сповіщень і транзакційних листів з вашого сайту до вхідних скриньок.','Set interval to once every'=>'Встановіть інтервал один раз на','Set the password:'=>'Встановіть пароль:','Set width to'=>'Встановіть ширину на','Share about ASE on:'=>'Поділіться інформацією про ASE на:','Show All'=>'Показати все','Show Custom Taxonomy Filters'=>'Показати власні фільтри таксономії','Show ID column'=>'Показати стовпчик ID','Show ID in action rows along with links for Edit, View, etc.'=>'Показувати ідентифікатор у рядках дій разом із посиланнями для редагування, перегляду тощо.','Show Less'=>'Показати менше','Show _MENU_ entries'=>'Виводити _MENU_ записів','Show a customizable maintenance page on the frontend while performing a brief maintenance to your site. Logged-in administrators can still view the site as usual.'=>'Відображати настроювану сторінку технічного обслуговування у фронтенді під час виконання короткого технічного обслуговування вашого сайту. Увійшовши в систему, адміністратори можуть переглядати сайт у звичайному режимі.','Show additional filter(s) on list tables for hierarchical, custom taxonomies.'=>'Показати додаткові фільтри на таблицях переліків для ієрархічних, власних таксономій.','Show admin bar status when search engines are set to be discouraged from indexing the site. This is set through a "Search engine visibility" checkbox in Settings >> Reading.'=>'Показувати стан панелі адміністратора, коли пошукові системи встановлені для відмови від індексації сайту. Це встановлюється через прапорець "Видимість для пошукових систем" в Налаштування >> Читання.','Show excerpt column'=>'Показати стовпчик з уривками','Show featured image column'=>'Показати стовпчик із зображеннями','Show file size column in media library'=>'Показати стовпчик розміру файлу в медіатеці','Show last modified column'=>'Показати колонку з датою модифікації','Show quick summary of the system the site is running on to admins, in the "At a Glance" dashboard widget. This includes the web server software, the PHP version, the database software and server IP address.'=>'Показуйте адміністраторам швидкий огляд системи, на якій працює сайт, у віджеті "З першого погляду" на інформаційній панелі. Сюди входить програмне забезпечення веб-сервера, версія PHP, програмне забезпечення бази даних та IP-адреса сервера.','Showing 0 to 0 of 0 entries'=>'Відображення від 0 до 0 з 0 записів','Showing _START_ to _END_ of _TOTAL_ entries'=>'Строки с _START_ по _END_ из _TOTAL_','Site Identity on Login Page'=>'Ідентифікація сайту на сторінці входу','Stripes'=>'Смуги','TLS'=>'TLS','Test email was successfully processed</span>.<br />Please check the destination email\'s inbox to verify successful delivery.'=>'Тестовий лист було успішно оброблено</span>.<br />Будь ласка, перевірте поштову скриньку отримувача, щоб переконатися в успішній доставці.','The current file will be replaced with the uploaded / selected file (of the same type) while retaining the current ID, publish date and file name. Thus, no existing links will break.'=>'Поточний файл буде замінено завантаженим/вибраним файлом (того ж типу) зі збереженням поточного ID, дати публікації та імені файлу. Таким чином, жодні існуючі посилання не будуть розірвані.','This site is undergoing maintenance for an extended period today. Thanks for your patience.'=>'Сьогодні цей сайт перебуває на тривалому технічному обслуговуванні. Дякуємо за ваше терпіння.','To exclude an image from conversion and resizing, append \'-nr\' suffix to the file name, e.g. bird-photo-4k-nr.jpg'=>'Щоб виключити зображення з конвертації та зміни розміру, додайте суфікс "-nr" до назви файлу, напр., bird-photo-4k-nr.jpg.','Translate'=>'Переклад','Trigger publishing of scheduled posts of all types marked with "missed schedule", anytime the site is visited.'=>'Запускати публікацію запланованих постів усіх типів з позначкою "пропущено за розкладом" у будь-який час відвідування сайту.','Use Selected Image'=>'Використати обране зображення','Use a shortcode like the following examples to display an email address on the frontend of your site: 
        		<ul>
        			<li><strong>[obfuscate email="john@example.com"]</strong> to display the email on it\'s own line</li>
        			<li><strong>[obfuscate email="john@example.com" display="inline"]</strong> to show the email inline</li>
        		</ul>'=>'Використовуйте шорткод, як показано в наступних прикладах, для відображення адреси електронної пошти на фронтенді вашого сайту: 
        		<ul>
        			<li><strong>[obfuscate email="john@example.com"]</strong> для відображення адреси в окремому рядку</li>
        			<li><strong>[obfuscate email="john@example.com" display="inline"]</strong> для відображення листа в рядку</li>
        		</ul>','Username'=>'Ім\'я користувача','Username only'=>'Тільки ім\'я користувача','Utilities'=>'Комунальні послуги','Validate with:'=>'Підтвердіть за допомогою:','Various Admin UI Enhancements'=>'Різні покращення інтерфейсу адміністратора','Various, smaller enhancements for different parts of the admin interface.'=>'Різноманітні дрібні покращення для різних частин інтерфейсу адміністратора.','View'=>'Перегляд','View Admin as Role'=>'Переглядайте адміністратора як роль.','View Content'=>'Переглянути вміст','View admin pages and the site (logged-in) as one of the non-administrator user roles.'=>'Перегляд сторінок адміністратора та сайту (після входу в систему) як один з ролей користувача, який не є адміністратором.','We\'ll be back soon.'=>'Ми скоро повернемося.','Welcome to WordPress'=>'Ласкаво просимо до WordPress','Wider Admin Menu'=>'Розширене меню адміністратора','Write a quick, 5-star review for ASE'=>'Напишіть швидкий, п\'ятизірковий відгук про ASE.','X / Twitter'=>'X / Twitter','YouTube'=>'YouTube','e.g. backend'=>'наприклад, бекенд','failed login attempts allowed before 15 minutes lockout'=>'невдалі спроби входу дозволені до 15-хвилинного блокування','for:'=>'для:','https://www.wpase.com/author-uri'=>'https://www.wpase.com/author-uri','https://www.wpase.com/plugin-uri'=>'https://www.wpase.com/plugin-uri','lockout(s) will block further login attempts for 24 hours'=>'блокування заблокує подальші спроби входу на 24 години','pixels <span class="faded">(Default is 1920 pixels)</span>'=>'пікселі <span class="faded">(початковий розмір - 1920 px)</span>','pixels. <span class="faded">(Default is 1920 pixels)</span>'=>'пікселів. <span class="faded">(За замовчуванням 1920 пікселів)</span>','revisions for:'=>'редакції для:','with AVIF support'=>'з підтримкою AVIF','without AVIF support'=>'без підтримки AVIF','wpase.com'=>'wpase.com']];
